// core: tier scorecard - weighted scoring picks the tier per workload
const tiers={cloud:{lat:1,cap:5,cost:4},fog:{lat:4,cap:3,cost:3},edge:{lat:5,cap:1,cost:5}};
const weights={lat:0.5,cap:0.3,cost:0.2};
const score=t=>tiers[t].lat*weights.lat+tiers[t].cap*weights.cap+tiers[t].cost*weights.cost;
const win=Object.keys(tiers).reduce((a,b)=>score(a)>=score(b)?a:b);
const ranked=Object.keys(tiers).sort((a,b)=>score(b)-score(a));
J({scores:{cloud:+score('cloud').toFixed(2),fog:+score('fog').toFixed(2),edge:+score('edge').toFixed(2)},winner:win,ranked});assert(ranked[0]==='fog'||ranked[0]==='edge','latency tier wins');assert(ranked.indexOf('fog')<=1,'fog top two');

// end-to-end: route three workloads to tiers by latency budget
const workloads=[{id:'train',budget_ms:600000},{id:'infer',budget_ms:15},{id:'filter',budget_ms:5}];
const tierOf=w=>w.budget_ms>1000?'cloud':(w.budget_ms>8?'fog':'edge');
const routed=workloads.map(w=>({id:w.id,tier:tierOf(w)}));
J({routed});assert(routed[0].tier==='cloud'&&routed[1].tier==='fog'&&routed[2].tier==='edge','routing');
